/* Lot 99: generated keyframes, accumulate, animation-timeline and hsl() paint in the reader sheet (generated by scripts/lot99_animgen.py; expectations from scripts/lot99_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
    TEST_ASSERT_EQUAL(1, g_d.nprops);
}

static void prep0(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare(&g_d, g_html, (int)strlen(g_html)));
}

static const char *nv(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { const char *v = wf_site_node_var(&g_d, i, "--p"); return v ? v : "(none)"; }
    return "(no node)";
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l99_sheet_0(void) {
    prep("@property --p { syntax: '<transform-list>'; inherits: false; initial-value: translatex(1in) rotate(338.1grad) skewy(45deg) } @keyframes k { 33.33% { --p: translatex(1in) translatex(-102.3px); animation-composition: add } } @keyframes j { 25% { --p: translatex(56%) skew(45deg); animation-composition: replace } } #o { animation: none 500ms linear, k 500ms linear; animation-timeline: none }", 500);
    TEST_ASSERT_EQUAL_STRING("translatex(96px) rotate(304.29deg) skewy(45deg)", nv("o"));
    TEST_ASSERT_EQUAL_STRING("translatex(96px) rotate(304.29deg) skewy(45deg)", nv("i"));
    TEST_ASSERT_EQUAL(0, g_d.prop_animated > 0);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(1, g_d.anim_idle);
    prep("@property --p { syntax: '<length>'; inherits: true; initial-value: 33.8px } @keyframes k { 0% { --p: -198.9246px } } @keyframes j { 50% { --p: 34.64px; animation-composition: replace } 60% { --p: 49.24px } } #o { animation-name: k; animation-duration: 500ms, 1s; animation-timing-function: linear; animation-composition: add, accumulate; animation-fill-mode: none }", 0);
    TEST_ASSERT_EQUAL_STRING("-165.1246px", nv("o"));
    TEST_ASSERT_EQUAL_STRING("-165.1246px", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated > 0);
    TEST_ASSERT_EQUAL(1, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_idle);
    prep("@property --p { syntax: '<length>+'; inherits: false; initial-value: 0px 0px } @keyframes k { 25% { --p: 46.78px 0px; animation-composition: replace } 50% { --p: 6.3px -103.672px } } @keyframes j { 50% { --p: 0px 0px } } #o { animation-name: k, j; animation-duration: 2s; animation-composition: accumulate }", 0);
    TEST_ASSERT_EQUAL_STRING("0px 0px", nv("o"));
    TEST_ASSERT_EQUAL_STRING("0px 0px", nv("i"));
    TEST_ASSERT_EQUAL(1, g_d.prop_animated > 0);
    TEST_ASSERT_EQUAL(1, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_idle);
    prep("@property --p { syntax: '<transform-list>'; inherits: true; initial-value: translate(1in, -86.22%) } @keyframes k { 0% { --p: scale(2) rotatex(0deg) rotate(0) } 50% { --p: scale(162%) translatex(1in) scale(1) } } @keyframes j { 50% { --p: scale(-5%, 1) translatex(0px) scale(1, 0.5); animation-composition: accumulate } } #o { animation-composition: accumulate; animation-name: k; animation-timeline: inherit; animation-duration: 1000ms; --p: scale(2, 0.5) translatex(153px) scale(1) }", 1020);
    TEST_ASSERT_EQUAL_STRING("scale(2, 0.5) translatex(153px) scale(1)", nv("o"));
    TEST_ASSERT_EQUAL_STRING("scale(2, 0.5) translatex(153px) scale(1)", nv("i"));
    TEST_ASSERT_EQUAL(0, g_d.prop_animated > 0);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    TEST_ASSERT_EQUAL(0, g_d.anim_idle);
}

